1	import { finding } from '../../../../engine/checks/helpers/findings.mjs';
2	import { VERSION_SOURCE, versionFromLiteral, compareVersions, nextVersion } from '../../../../engine/version-format.mjs';
3	
4	// A PACK'S CONTENT IS DELIVERED ON ITS VERSION NUMBER, and on nothing else. The
5	// engine tree vendors wholesale on every converge; a pack's directory ships only
6	// where `planPackUpdates` sees `installed.packVersions[id] < pack.version`
7	// (updates/pack-update.mjs). So a canon commit that edits `packs/<id>/` without
8	// touching that number lands here, goes green here, and reaches no member — the
9	// fleet keeps the old bytes while canon believes the change shipped.
10	//
11	// #939 is what that costs. A check vocabulary rename updated the engine and the
12	// canon's own packs in one commit: the engine, delivered unconditionally, reached
13	// every member and rejected the old spelling; the pack carrying the new spelling
14	// stayed at `version: 1` and reached nobody. The mixed tree failed each member's
15	// self-test, the update PR parked, and the fix could not arrive by the route that
16	// delivers fixes. Seven repos sat frozen for five days.
17	//
18	// So the invariant this rule holds is one line: A CHANGE UNDER `packs/<id>/` IS A
19	// CHANGE TO THAT PACK'S VERSION. Every SHIPPING byte counts, because every one of
20	// them rides the same directory copy — prose, a skill, a check module, a migration
21	// record. A pack's tests sit beside the files they cover and are the one thing in
22	// that directory no vendor set carries (compute-vendor-set drops `*.test.mjs`), so
23	// nobody is waiting on them and a bump for one would re-deliver every pack in the
24	// tree to say nothing.
25	// It is the pack-side twin of `engine-release-record` (the claudinite local pack),
26	// which holds the same line for `ENGINE_VERSION`.
27	//
28	// WORK SCOPE: the question is what THIS change did. The tree always contains a
29	// version number; only the diff says whether it moved with the content beside it.
30	const LOCAL_PACKS = '.claudinite/local/packs';
31	
32	// The pack ids a changed-file list touches, in first-seen order. Anchored at
33	// `packs/<id>/` so the canon's own local packs (which vendor nowhere, carry no
34	// version and reach no member) and the tree's own files (`packs/README.md`,
35	// `packs/directory.GENERATED.md`) are outside it by construction. Tests drop out for
36	// the same reason the local packs do: nothing delivers them.
37	export function packsTouched(changed) {
38	  const ids = [];
39	  for (const file of changed ?? []) {
40	    if (file.startsWith(`${LOCAL_PACKS}/`) || file.endsWith('.test.mjs')) continue;
41	    const m = /^packs\/([^/]+)\//.exec(file);
42	    if (m && !ids.includes(m[1])) ids.push(m[1]);
43	  }
44	  return ids;
45	}
46	
47	// The `version:` a pack manifest declares, or null when it declares none (a
48	// manifest that is absent on one side of the diff, or one the schema check owns).
49	// The preceding-character class is what keeps `minEngineVersion:` out of it.
50	const PACK_VERSION_RE = new RegExp(String.raw`(?:^|[\s{,])version:\s*'?(${VERSION_SOURCE})'?`, 'm');
51	export function declaredPackVersion(text) {
52	  const m = PACK_VERSION_RE.exec(text ?? '');
53	  return m ? versionFromLiteral(m[1]) : null;
54	}
55	
56	const rule = {
57	  id: 'pack-version-bumped',
58	  severity: 'blocking',
59	  scope: 'work',
60	  description: 'A change under packs/<id>/ bumps that pack\'s version',
61	  doc: 'docs/versioned-updates/DESIGN.md',
62	  why: 'a member receives a pack directory only when the canon\'s version exceeds the one it has installed, so content edited without a bump reaches nobody while canon CI reports it shipped (#939 froze seven repos for five days that way)',
63	
64	  run(work) {
65	    const findings = [];
66	    for (const id of packsTouched(work.changedFiles)) {
67	      const manifest = `packs/${id}/pack.mjs`;
68	      const head = declaredPackVersion(work.read(manifest));
69	      if (head === null) continue;                     // the pack was deleted, or declares no version — other rules own that
70	      const base = declaredPackVersion(work.readBase(manifest));
71	      if (base === null) continue;                     // a pack this change introduces: its first version ships to everyone
72	      const moved = compareVersions(head, base);
73	      if (moved > 0) continue;
74	
75	      findings.push(finding(rule, {
76	        file: manifest,
77	        what: moved === 0
78	          ? `this change edits packs/${id}/ but leaves its version at ${head}`
79	          : `packs/${id}/ moves its version backwards, ${base} → ${head}`,
80	        fix: moved === 0
81	          ? `raise \`version\` in ${manifest} to '${nextVersion(base)}' — the version is the whole delivery signal, so an edit `
82	            + 'that does not move it stays in the canon forever'
83	          : 'pack versions only ever increase — the update flow reads them as an ordering, so a lowered number tells '
84	            + 'every member it is already up to date',
85	      }));
86	    }
87	    return findings;
88	  },
89	};
90	
91	export default rule;

