1	import { finding } from '../../../../engine/checks/helpers/findings.mjs';
2	import { VERSION_SOURCE, versionFromLiteral, compareVersions } from '../../../../engine/version-format.mjs';
3	
4	// An ENGINE RELEASE is a bump of ENGINE_VERSION, and a bump is only legitimate
5	// once the live canary rehearsal has passed against the tree being released
6	// (docs/versioned-updates/DESIGN.md §2.1; owner decision, 2026-08-12). That is a
7	// claim about a run in another repository, so no check can verify it — but a
8	// check can insist the claim is MADE, in the one place a later reader will look,
9	// with the run id that settles it.
10	//
11	// Which is the whole job here: a bump must land with its row in
12	// engine/RELEASES.md, and that row must cite the rehearsal run. Without this the
13	// evidence lives in whoever ran it, and "was version 4 ever canaried?" becomes
14	// unanswerable a week later — the version stamped on every member in the fleet,
15	// with nothing behind it.
16	//
17	// WORK SCOPE, like consumer-safe-change beside it: the question is what THIS
18	// change did, and the tree always contains a version and a log.
19	//
20	// It also refuses a bump that does not move forward. Versions are the ordering
21	// the update flows range over — migrations apply for `installed < target` — so a
22	// repeated or lowered number does not read as a mistake downstream, it reads as
23	// "nothing to do" on every member at once.
24	const VERSION_FILE = 'engine/version.mjs';
25	export const RELEASES = 'engine/RELEASES.md';
26	
27	// The run link a row must carry: an Actions run in this repo. Matched by shape
28	// rather than by repo name — a fork or a rename must not make the rule unsatisfiable.
29	const RUN_URL = /https:\/\/github\.com\/[^/\s]+\/[^/\s]+\/actions\/runs\/\d+/;
30	
31	// The declared version in a version.mjs source, or null when it says nothing
32	// (a missing file at the base — the module's first appearance).
33	const ENGINE_VERSION_RE = new RegExp(String.raw`export const ENGINE_VERSION = '?(${VERSION_SOURCE})'?\s*;`);
34	export function declaredVersion(text) {
35	  const m = ENGINE_VERSION_RE.exec(text ?? '');
36	  return m ? versionFromLiteral(m[1]) : null;
37	}
38	
39	// Does the log carry a row for this version citing a rehearsal run? The row is a
40	// table row whose first cell is the bare number, so the log stays a table a human
41	// reads rather than a machine format the check invented.
42	const ROW_VERSION_RE = new RegExp(String.raw`^\|\s*(${VERSION_SOURCE})\s*\|`);
43	export function releaseRowFor(text, version) {
44	  for (const line of (text ?? '').split('\n')) {
45	    const m = ROW_VERSION_RE.exec(line.trim());
46	    const row = m && versionFromLiteral(m[1]);
47	    if (row !== null && row !== false && compareVersions(row, version) === 0) return RUN_URL.test(line) ? 'ok' : 'no-run';
48	  }
49	  return 'missing';
50	}
51	
52	const rule = {
53	  id: 'engine-release-record',
54	  severity: 'blocking',
55	  scope: 'work',
56	  description: 'A bump of ENGINE_VERSION lands with its RELEASES.md row, citing the canary rehearsal that qualified it',
57	  doc: 'engine/RELEASES.md',
58	  why: 'the canary runs in another repository, so the run id is the only durable evidence a released version was ever rehearsed — unrecorded, it is unanswerable a week later, on a number every member is stamped with',
59	
60	  run(work) {
61	    const changed = work.changedFiles ?? [];
62	    if (!changed.includes(VERSION_FILE)) return [];
63	    const head = declaredVersion(work.read(VERSION_FILE));
64	    const base = declaredVersion(work.readBase(VERSION_FILE));
65	    if (head === null) return [];                       // not a version edit (or a deletion — other rules own that)
66	    if (base !== null && compareVersions(head, base) === 0) return [];      // the file changed, the version did not: an ordinary engine edit
67	
68	    if (base !== null && compareVersions(head, base) < 0) {
69	      return [finding(rule, {
70	        file: VERSION_FILE,
71	        what: `ENGINE_VERSION moves backwards, ${base} → ${head}`,
72	        fix: 'engine versions only ever increase — the update flows read them as an ordering, so a lowered number tells every member it is already up to date',
73	      })];
74	    }
75	
76	    const state = releaseRowFor(work.read(RELEASES), head);
77	    if (state === 'ok') return [];
78	    return [finding(rule, {
79	      file: RELEASES,
80	      what: state === 'missing'
81	        ? `this change releases engine version ${head}, and ${RELEASES} carries no row for it`
82	        : `the ${RELEASES} row for engine version ${head} cites no canary rehearsal run`,
83	      fix: `dispatch the canary rehearsal against this branch, wait for it to pass, then add a row for version ${head} `
84	        + 'linking that run — a release is a snapshot the canary has qualified, and the link is what says it was',
85	    })];
86	  },
87	};
88	
89	export default rule;

